 "content": "from collections import deque


def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    objects = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or (r, c) in seen:
                continue
            q = [(r, c)]
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.pop()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    p = (y + dy, x + dx)
                    if (0 <= p[0] < h and 0 <= p[1] < w and p not in seen
                            and grid[p[0]][p[1]] == color):
                        seen.add(p)
                        q.append(p)
            y0 = min(y for y, x in cells)
            y1 = max(y for y, x in cells)
            x0 = min(x for y, x in cells)
            x1 = max(x for y, x in cells)
            local = {(y - y0, x - x0) for y, x in cells}
            bh, bw = y1 - y0 + 1, x1 - x0 + 1
            # A zero region enclosed within the object's bounding box marks a hollow object.
            outside = set()
            qq = deque()
            for yy in range(bh):
                for xx in range(bw):
                    if yy in (0, bh - 1) or xx in (0, bw - 1):
                        if (yy, xx) not in local and (yy, xx) not in outside:
                            outside.add((yy, xx))
                            qq.append((yy, xx))
            while qq:
                yy, xx = qq.popleft()
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = yy + dy, xx + dx
                    if (0 <= ny < bh and 0 <= nx < bw and (ny, nx) not in local
                            and (ny, nx) not in outside):
                        outside.add((ny, nx))
                        qq.append((ny, nx))
            hollow = any((yy, xx) not in local and (yy, xx) not in outside
                         for yy in range(bh) for xx in range(bw))
            objects.append({'color': color, 'cells': cells, 'local': local,
                            'y': y0, 'x': x0, 'bh': bh, 'hollow': hollow})

    # Hollow objects rise; solid objects fall. When objects share a path,
    # preserve their order and let them stop against the already settled object.
    placed = []
    for direction in (-1, 1):
        group = [o for o in objects if (o['hollow'] and direction == -1)
                 or (not o['hollow'] and direction == 1)]
        group.sort(key=lambda o: o['y'], reverse=(direction == 1))
        settled = []
        for o in group:
            y = o['y']
            while True:
                ny = y + direction
                if ny < 0 or ny + o['bh'] > h:
                    break
                newcells = {(ny + ly, o['x'] + lx) for ly, lx in o['local']}
                if any(newcells & other for other in settled):
                    break
                y = ny
            finalcells = {(y + ly, o['x'] + lx) for ly, lx in o['local']}
            settled.append(finalcells)
            placed.append((o['color'], finalcells))

    out = [[0 for _ in range(w)] for _ in range(h)]
    for color, cells in placed:
        for y, x in cells:
            out[y][x] = color
    return out
